#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Entities
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.destroyOnSlab)]
    public class DestroyOnSlabBehaviour : EntityBehaviourDefinition
    {
        public DestroyOnSlabBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            if (entity.IsOnSlab())
            {
                entity.Die();
            }
        }
    }

}
